parameters.jsCode:
// Combine LLM text + PDF output
const [textItem, pdfItem] = items;

// Extract reply (from frontend agent)
const reply = textItem.json.reply || textItem.json.output || null;

// Extract PDF (from pdf generator node)
let pdfResult = null;

if (pdfItem.binary) {
  const key = Object.keys(pdfItem.binary)[0];
  if (key && pdfItem.binary[key].data) {
    pdfResult = `data:application/pdf;base64,${pdfItem.binary[key].data}`;
  }
}

return [
  {
    json: {
      reply,
      pdf: pdfResult
    }
  }
];

